import { defineConfig } from '@playwright/test';

/** Software WebGL2 for every test; the camera spec adds Chromium's fake media device. */
export const CHROMIUM_ARGS = ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'];
export const EXECUTABLE = process.env.CHROMIUM_PATH ? { executablePath: process.env.CHROMIUM_PATH } : {};

/**
 * E2E: the built app in Chromium with software WebGL2, against the synthetic
 * fixture terrain. No network. Run `bun run build` first; the fixture tiles
 * are generated by the global setup.
 */
export default defineConfig({
  testDir: '.',
  testMatch: /.*\.spec\.ts/,
  globalSetup: './global-setup.ts',
  // Each test loads the terrain in software WebGL, twice when it reloads: a
  // slow CI runner needs well over two minutes for that.
  timeout: 240_000,
  expect: { timeout: 30_000, toHaveScreenshot: { maxDiffPixelRatio: 0.02 } },
  // One page at a time: SwiftShader is CPU-bound, and with three workers the
  // colour tests (shade pass, ~1 s a frame) and the sensor test (the view
  // follows in the frame loop) ran into their 30 s polls on the CI runner
  // while three workers gained only two minutes locally (12.4 → 10.4 min).
  // E2E_WORKERS=3 for a quick local run on a machine with cores to spare.
  fullyParallel: false,
  workers: Number(process.env.E2E_WORKERS ?? 1),
  retries: 0,
  reporter: process.env.CI ? [['list'], ['html', { open: 'never', outputFolder: '../../playwright-report/e2e' }]] : 'list',
  outputDir: '../../test-results/e2e',
  snapshotPathTemplate: '{testDir}/__screenshots__/{testFileName}/{arg}{ext}',
  use: {
    baseURL: 'http://localhost:4173',
    viewport: { width: 1000, height: 600 },
    deviceScaleFactor: 1,
    launchOptions: { ...EXECUTABLE, args: CHROMIUM_ARGS },
    trace: 'retain-on-failure',
  },
  webServer: {
    command: 'node tools/serve.mjs 4173',
    url: 'http://localhost:4173/dist/',
    cwd: '../..',
    reuseExistingServer: !process.env.CI,
    timeout: 20_000,
  },
});
